from pathlib import Path

def replace_once(path, old, new):
    p = Path(path)
    s = p.read_text()
    if s.count(old) != 1:
        raise SystemExit(f'{path}: expected one match for {old!r}, found {s.count(old)}')
    p.write_text(s.replace(old, new, 1))

