p.write_text("""function exposeWindowStorage(name: 'localStorage' | 'sessionStorage') {
\tif (typeof window === 'undefined') return;
\tconst storage = name === 'localStorage' ? window.localStorage : window.sessionStorage;
\tObject.defineProperty(globalThis, name, {
\t\tconfigurable: true,
\t\tenumerable: true,
\t\tvalue: storage,
\t\twritable: true
\t});
}

exposeWindowStorage('localStorage');
exposeWindowStorage('sessionStorage');
""")

